    function testFuzz_property(uint256 depositAmount, uint256 fuzzSeed) public {
        vm.assume(depositAmount > 0 && depositAmount < 1 ether);
        address caller = address(uint160(uint256(keccak256(abi.encodePacked(fuzzSeed)))));
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.addToBalance{value: depositAmount}();

        uint256 balanceBefore = c.getBalance(caller);
        vm.prank(caller);
        bool ok = true;
        try c.withdrawBalance() {
        } catch {
            ok = false;
        }
        if (ok) {
            uint256 balanceAfter = c.getBalance(caller);
            assertTrue(balanceAfter == 0);
        }
    }
}
